/* GVSMARTPAY — Service Worker untuk notifikasi push (Firebase Cloud Messaging).
   WAJIB: file ini harus berada di ROOT domain, yaitu https://<domainmu>/firebase-messaging-sw.js
   Di Vercel: taruh di folder /public/firebase-messaging-sw.js pada project-mu (atau di root
   project kalau kamu tidak memakai struktur /public), lalu deploy ulang. */

importScripts('https://www.gstatic.com/firebasejs/10.12.2/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/10.12.2/firebase-messaging-compat.js');

// Samakan persis dengan FIREBASE_CONFIG di gvsmartpay-ungu.html
firebase.initializeApp({
  apiKey: 'AIzaSyB67VZXJzrQZFF6SNdgzDzdiP6k8zGfvN8',
  authDomain: 'gvsmartpay.firebaseapp.com',
  projectId: 'gvsmartpay',
  storageBucket: 'gvsmartpay.firebasestorage.app',
  messagingSenderId: '1015873707904',
  appId: '1:1015873707904:web:1dfde5cc20d7e62f8eab65'
});

// Langsung aktif tanpa menunggu tab lama ditutup, supaya perbaikan notifikasi cepat berlaku.
self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', (e) => e.waitUntil(self.clients.claim()));

const messaging = firebase.messaging();

// Konfirmasi ke server bahwa notifikasi SUDAH ditampilkan (untuk log pengiriman admin). Gagal/offline = diabaikan, tidak mengganggu tampilan.
function ack(d) {
  if (!d || !d.lid || !d.sig) return Promise.resolve();
  return fetch('/api/notify', { method: 'POST', keepalive: true, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action: 'ack', lid: d.lid, sig: d.sig }) }).catch(() => {});
}

// Notifikasi yang datang saat aplikasi TIDAK sedang dibuka (tab tertutup / di background).
messaging.onBackgroundMessage((payload) => {
  // Server mengirim DATA-ONLY, jadi kita yang menampilkan notifikasinya (app tertutup / di background).
  const d = payload.data || {};
  const title = d.title || (payload.notification && payload.notification.title) || 'GVSMARTPAY';
  const body = d.body || (payload.notification && payload.notification.body) || '';
  return self.registration.showNotification(title, {
    body,
    icon: "data:image/png;base64,",
    badge: "data:image/png;base64,",
    tag: d.tag || undefined,
    renotify: true,
    timestamp: Number(d.ts) || Date.now(),
    requireInteraction: false,
    vibrate: [200, 100, 200],
    data: { url: d.url || '/' }
  }).then(() => ack(d));
});
// Klik notifikasi -> buka/fokuskan aplikasi dan arahkan ke halaman terkait (?go=...).
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  let url = (event.notification.data && event.notification.data.url) || '/';
  try { const u = new URL(url, self.location.origin); url = u.origin === self.location.origin ? (u.pathname + u.search + u.hash) : '/'; } catch (e) { url = '/'; } // tidak pernah membuka alamat luar
  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((list) => {
      for (const c of list) {
        if ('focus' in c) { try { c.postMessage({ go: url }); } catch (e) {} return c.focus(); }
      }
      if (clients.openWindow) return clients.openWindow(url);
    })
  );
});
